head.b:skin:
*{font-family:Roboto,Arial,Helvetica,sans-serif}
body{margin:0;background:#ffffff;font-family:Roboto,Arial,Helvetica,sans-serif;color:#222;font-size:15.5px;line-height:1.6}
input,button,select,textarea{font-family:Roboto,Arial,Helvetica,sans-serif}
a{color:#0645d9;text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto}
.wrap{width:1078px;max-width:calc(100% - 16px);margin:0 auto;background:#fff}
.head{background:#a40000;color:#fff;text-align:center;padding:15px 10px}
.brand-logo{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;border:2px solid #fff;border-radius:6px;background:#fff;color:#a40000;font-weight:bold;font-size:20px;line-height:1;margin:0 auto 6px}
.head h1{margin:0;font-size:35px;line-height:1.08}
.head h1 a{color:#fff;text-decoration:none}
.head p{margin:4px 0 0;font-size:14.5px}
.nav{background:#073a8c;text-align:center;border-bottom:3px solid #ffcc00}
.nav a{display:inline-block;color:#fff;text-decoration:none;padding:9px 11px;font-size:14.5px;font-weight:bold}
.ticker{text-align:center;font-size:14.5px;padding:9px;border-bottom:1px solid #ddd}
.breaking{display:flex;align-items:center;border-bottom:1px solid #ddd;background:#fff7ed;font-size:14.5px;overflow:hidden}
.breaking-title{background:#a40000;color:#fff;font-weight:700;padding:9px 11px;white-space:nowrap}
.breaking-list{flex:1;overflow:hidden;white-space:nowrap;padding:0 8px}
.breaking-list marquee{display:block}
.breaking-list a{font-weight:500;margin-right:22px;color:#0645d9}
.buttons{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin:10px 0}
.buttons a{color:#fff;text-align:center;text-decoration:none;padding:9px 6px;font-weight:bold;font-size:14.5px;border-radius:6px}
.buttons a:nth-child(1){background:#f97316}.buttons a:nth-child(2){background:#16a34a}.buttons a:nth-child(3){background:#2563eb}.buttons a:nth-child(4){background:#dc2626}
.buttons a:nth-child(5){background:#db2777}.buttons a:nth-child(6){background:#7c3aed}.buttons a:nth-child(7){background:#0891b2}.buttons a:nth-child(8){background:#15803d}
.adbox{background:#1f2937;color:#fff;min-height:90px;margin:10px 0;border-radius:4px;display:flex;align-items:center;justify-content:center;text-align:center;padding:16px;font-weight:bold}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:12px 0}
.box{border:1px solid #bdbdbd;background:#fff;min-height:245px}
.box h2{background:#a40000;color:#fff;font-size:17.5px;margin:0;padding:8px;text-align:center}
.box ul{margin:0;padding:8px 8px 8px 24px;min-height:0}
.box li{margin:0 0 8px;font-size:14.5px;line-height:1.45}
.box .last-date{display:block;margin-top:2px;color:#b91c1c;font-size:12.8px;font-weight:700}
.box .last-date.urgent{color:#dc2626;animation:lastDateBlink 1s step-start infinite}
@keyframes lastDateBlink{50%{opacity:.2}}
.more{display:block;margin:0 8px 8px auto;width:max-content;background:#1d70b8;color:#fff!important;text-decoration:none;padding:6px 9px;border-radius:2px;font-size:13.2px}
.intro{margin:18px 0;font-size:15.5px;line-height:1.75;text-align:justify;text-justify:inter-word}
.intro h2{font-size:24px;margin:15px 0 9px;color:#333}
.seo-bottom{border-top:1px solid #e5e7eb;margin-top:16px;padding-top:12px}
.seo-bottom p{font-size:14.5px;color:#374151;text-align:justify;text-justify:inter-word}
.post-outer{border:1px solid #ddd;margin:0 0 12px;padding:12px;background:#fff}
.post-title,.post-title a{font-size:24px;color:#a40000;margin:0 0 9px;text-decoration:none}
.post-body{font-size:16.5px;line-height:1.78}
.post-body h2{background:#b91c1c;color:#fff;font-size:20px;margin:19px 0 9px;padding:9px 11px;border-radius:3px}
.post-body table{width:100%;border-collapse:collapse;margin:10px 0}
.post-body th,.post-body td{border:1px solid #d1d5db;padding:10px;text-align:left;vertical-align:top}
.post-body th{background:#f3f4f6}
.official-link-btn,.post-body table td a.official-link-btn{display:inline-block;background:#15803d;color:#fff!important;padding:8px 13px;border-radius:6px;font-weight:700;text-decoration:none;line-height:1.2;box-shadow:0 1px 2px rgba(0,0,0,.16)}
.official-link-btn:hover,.post-body table td a.official-link-btn:hover{background:#166534;text-decoration:none}
.foot{background:#3b82f6;color:#fff;text-align:center;padding:16px;font-size:14.5px;margin-top:20px}
.foot a{color:#fff}
@media(max-width:760px){.wrap{width:auto;max-width:100%;padding:0 8px;box-sizing:border-box}.head h1{font-size:27.5px}.grid{grid-template-columns:1fr}.buttons{grid-template-columns:repeat(2,1fr)}.nav a{font-size:13.2px;padding:8px}.post-title,.post-title a{font-size:21px}.post-body{font-size:16px}.post-body th,.post-body td{display:block;width:auto;box-sizing:border-box}}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
  (function(){
    var home = document.getElementById('homepageContent');
    var path = window.location.pathname.replace(/\/+$/, '/');
    var isHome = path === '/' || path === '/index.html';
    if (home && !isHome) {
      home.style.display = 'none';
    }
    if (isHome) {
      loadBreakingLatest();
      loadHomeCategory('Latest Jobs', 'home-latest-jobs');
      loadHomeCategory('Results', 'home-results');
      loadHomeCategory('Admit Card', 'home-admit-card');
      loadHomeCategory('Government Jobs', 'home-government-jobs');
      loadHomeCategory('Railway Jobs', 'home-railway-jobs');
      loadHomeCategory('Bank Jobs', 'home-bank-jobs');
      loadHomeCategory('Answer Key', 'home-answer-key');
      loadHomeCategory('Syllabus', 'home-syllabus');
      loadHomeCategory('Defence Jobs', 'home-defence-jobs');
    }
    if (!isHome) {
      var target = document.getElementById('postContentEmergency');
      var body = document.querySelector('.post-body');
      var hasBody = body && body.textContent.replace(/\s+/g, '').length > 30;
      if (target && !hasBody) {
        target.style.display = 'block';
        var labelMatch = window.location.pathname.match(/\/search\/label\/([^\/]+)/);
        if (labelMatch) {
          var label = decodeURIComponent(labelMatch[1].replace(/\+/g, ' '));
          target.innerHTML = '<article class="post-outer"><h1 class="post-title">' + label + '</h1><div class="post-body">Category posts load ho rahe hain.</div></article>';
          fetch('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=25&orderby=updated')
            .then(function(r){ return r.json(); })
            .then(function(data){
              var entries = data.feed && data.feed.entry ? data.feed.entry : [];
              if (!entries.length) {
                target.innerHTML = '<article class="post-outer"><h1 class="post-title">' + label + '</h1><div class="post-body">Is category me abhi posts nahi hain.</div></article>';
                return;
              }
              var html = '<article class="post-outer"><h1 class="post-title">' + label + '</h1><div class="post-body"><ul>';
              entries = sortEntriesByUpdated(entries);
              for (var i = 0; i < entries.length; i++) {
                var url = '#';
                var links = entries[i].link || [];
                for (var j = 0; j < links.length; j++) {
                  if (links[j].rel === 'alternate') { url = links[j].href; break; }
                }
                html += '<li><a href="' + url + '">' + entries[i].title.$t + '</a></li>';
              }
              html += '</ul></div></article>';
              target.innerHTML = html;
            })
            .catch(function(){
              target.innerHTML = '<article class="post-outer"><h1 class="post-title">Category feed blocked hai</h1><div class="post-body">Blogger Settings > Site feed > Allow blog feed = Full set karein.</div></article>';
            });
          return;
        }
        target.innerHTML = '<article class="post-outer"><h1 class="post-title">Loading post...</h1><div class="post-body">Post content load ho raha hai.</div></article>';
        var pagePostId = getCurrentPostId();
        var postFeedUrl = pagePostId ? ('/feeds/posts/default/' + pagePostId + '?alt=json-in-script') : '/feeds/posts/default?alt=json-in-script&max-results=150&orderby=updated';
        loadJsonp(postFeedUrl, function(data){
            var entries = data.entry ? [data.entry] : sortEntriesByUpdated(data.feed && data.feed.entry ? data.feed.entry : []);
            var currentUrl = normalizePostUrl(location.href);
            var found = data.entry ? data.entry : null;
            for (var i = 0; i < entries.length; i++) {
              var links = entries[i].link || [];
              for (var j = 0; j < links.length; j++) {
                if (links[j].rel === 'alternate') {
                  var entryUrl = normalizePostUrl(links[j].href);
                  if (entryUrl === currentUrl) {
                    found = entries[i];
                    break;
                  }
                }
              }
              if (found) { break; }
            }
            if (!found) {
              target.innerHTML = '<article class="post-outer"><h1 class="post-title">Content load nahi hua</h1><div class="post-body">Page hard refresh karein. Agar issue continue ho to Blogger Settings > Site feed > Allow blog feed = Full set karein.</div></article>';
              return;
            }
            var title = found.title && found.title.$t ? found.title.$t : 'Post';
            var content = found.content && found.content.$t ? found.content.$t : '';
            target.innerHTML = '<article class="post-outer"><h1 class="post-title">' + title + '</h1><div class="post-body entry-content">' + content + '</div></article>';
          }, function(){
            target.innerHTML = '<article class="post-outer"><h1 class="post-title">Content load nahi hua</h1><div class="post-body">Page hard refresh karein. Agar phir bhi issue aaye to Blogger Settings > Site feed > Allow blog feed = Full set karein.</div></article>';
          });
      }
    }

    function loadJsonp(url, onSuccess, onError) {
      var callbackName = 'tdjFeedCallback_' + Math.random().toString(36).slice(2);
      var script = document.createElement('script');
      var done = false;
      window[callbackName] = function(data) {
        done = true;
        try { onSuccess(data || {}); } finally { cleanup(); }
      };
      function cleanup() {
        try { delete window[callbackName]; } catch (e) { window[callbackName] = null; }
        if (script && script.parentNode) { script.parentNode.removeChild(script); }
      }
      script.onerror = function() {
        if (!done) {
          cleanup();
          onError();
        }
      };
      script.src = url + '&callback=' + callbackName;
      document.head.appendChild(script);
      setTimeout(function(){
        if (!done) {
          cleanup();
          onError();
        }
      }, 12000);
    }

    function getCurrentPostId() {
      var commentFeed = document.querySelector('link[href*="/feeds/"][href*="/comments/default"]');
      if (commentFeed) {
        var href = commentFeed.getAttribute('href') || '';
        var feedMatch = href.match(/\/feeds\/(\d{8,})\/comments\/default/);
        if (feedMatch) { return feedMatch[1]; }
      }
      var html = document.documentElement ? document.documentElement.innerHTML : '';
      var match = html.match(/postId['"]?\s*:\s*['"]?(\d{8,})/);
      return match ? match[1] : '';
    }

    function normalizePostUrl(url) {
      return String(url || '')
        .split('?')[0]
        .replace(/^https?:\/\//, '')
        .replace(/^www\./, '')
        .replace(/\/$/, '');
    }

    function loadHomeCategory(label, targetId) {
      var target = document.getElementById(targetId);
      if (!target) { return; }
      fetch('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=10&orderby=updated')
        .then(function(r){ return r.json(); })
        .then(function(data){
          var entries = sortEntriesByUpdated(data.feed && data.feed.entry ? data.feed.entry : []);
          if (!entries.length) {
            target.innerHTML = '<li>No posts found</li>';
            return;
          }
          var html = '';
          for (var i = 0; i < entries.length; i++) {
            var postUrl = '#';
            var links = entries[i].link || [];
            for (var j = 0; j < links.length; j++) {
              if (links[j].rel === 'alternate') {
                postUrl = links[j].href;
                break;
              }
            }
            var lastDate = label === 'Latest Jobs' ? getActiveLastDate(entries[i]) : null;
            html += '<li><a href="' + postUrl + '">' + entries[i].title.$t + '</a>' + (lastDate ? '<span class="last-date' + (lastDate.urgent ? ' urgent' : '') + '">Last Date: ' + lastDate.text + '</span>' : '') + '</li>';
          }
          target.innerHTML = html;
        })
        .catch(function(){
          target.innerHTML = '<li>Feed loading failed</li>';
        });
    }

    function getActiveLastDate(entry) {
      var rawDate = extractLastDate(entry);
      var date = parseLastDate(rawDate);
      if (!date) { return null; }
      var today = new Date();
      today.setHours(0, 0, 0, 0);
      date.setHours(0, 0, 0, 0);
      var daysLeft = Math.round((date.getTime() - today.getTime()) / 86400000);
      if (daysLeft < 0) { return null; }
      return { text: rawDate, urgent: daysLeft <= 3 };
    }

    function extractLastDate(entry) {
      var html = (entry.content && entry.content.$t) || (entry.summary && entry.summary.$t) || '';
      var text = html.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
      var patterns = [
        /(?:online apply last date|last date to apply|apply last date|last date for application|online apply last|last date)\s*[:\-]?\s*([0-9]{1,2}\s+[A-Za-z]+\s+[0-9]{4})/i,
        /(?:online apply last date|last date to apply|apply last date|last date for application|online apply last|last date)\s*[:\-]?\s*([0-9]{1,2}[\/\-][0-9]{1,2}[\/\-][0-9]{2,4})/i
      ];
      for (var i = 0; i < patterns.length; i++) {
        var match = text.match(patterns[i]);
        if (match && match[1]) { return match[1].trim(); }
      }
      return '';
    }

    function parseLastDate(value) {
      if (!value) { return null; }
      var clean = value.replace(/,/g, ' ').replace(/\s+/g, ' ').trim();
      var monthMap = {
        january:0, jan:0, february:1, feb:1, march:2, mar:2, april:3, apr:3,
        may:4, june:5, jun:5, july:6, jul:6, august:7, aug:7, september:8, sep:8, sept:8,
        october:9, oct:9, november:10, nov:10, december:11, dec:11
      };
      var wordMatch = clean.match(/^([0-9]{1,2})\s+([A-Za-z]+)\s+([0-9]{4})$/);
      if (wordMatch) {
        var month = monthMap[wordMatch[2].toLowerCase()];
        if (month === undefined) { return null; }
        return new Date(Number(wordMatch[3]), month, Number(wordMatch[1]));
      }
      var numMatch = clean.match(/^([0-9]{1,2})[\/\-]([0-9]{1,2})[\/\-]([0-9]{2,4})$/);
      if (numMatch) {
        var year = Number(numMatch[3]);
        if (year < 100) { year += 2000; }
        return new Date(year, Number(numMatch[2]) - 1, Number(numMatch[1]));
      }
      return null;
    }

    function loadBreakingLatest() {
      var target = document.getElementById('breakingLatest');
      if (!target) { return; }
      fetch('/feeds/posts/default?alt=json&max-results=10&orderby=updated')
        .then(function(r){ return r.json(); })
        .then(function(data){
          var entries = sortEntriesByUpdated(data.feed && data.feed.entry ? data.feed.entry : []);
          if (!entries.length) {
            target.innerHTML = '<marquee behavior="scroll" direction="left" scrollamount="4">No latest posts found</marquee>';
            return;
          }
          var html = '<marquee behavior="scroll" direction="left" scrollamount="4">';
          for (var i = 0; i < entries.length; i++) {
            var postUrl = '#';
            var links = entries[i].link || [];
            for (var j = 0; j < links.length; j++) {
              if (links[j].rel === 'alternate') { postUrl = links[j].href; break; }
            }
            html += '<a href="' + postUrl + '">' + entries[i].title.$t + '</a>';
          }
          html += '</marquee>';
          target.innerHTML = html;
        })
        .catch(function(){
          target.innerHTML = '<marquee behavior="scroll" direction="left" scrollamount="4">Latest posts feed loading failed</marquee>';
        });
    }

    function sortEntriesByUpdated(entries) {
      return entries.slice().sort(function(a, b) {
        var aTime = Date.parse((a.updated && a.updated.$t) || (a.published && a.published.$t) || 0);
        var bTime = Date.parse((b.updated && b.updated.$t) || (b.published && b.published.$t) || 0);
        return bTime - aTime;
      });
    }
  })();
//
